class Solution {
public:
    double maxAmount(string initialCurrency, vector<vector<string>>& pairs1, vector<double>& rates1, vector<vector<string>>& pairs2, vector<double>& rates2) {
        auto getMaxHoldings = [](const string& startCurr, double baseAmt, const vector<vector<string>>& pairs, const vector<double>& rates) {
            unordered_map<string, vector<pair<string, double>>> graph;
            for (size_t i = 0; i < pairs.size(); ++i) {
                graph[pairs[i][0]].push_back({pairs[i][1], rates[i]});
                graph[pairs[i][1]].push_back({pairs[i][0], 1.0 / rates[i]});
            }
            unordered_map<string, double> best;
            best[startCurr] = baseAmt;
            queue<pair<string, double>> q;
            q.push({startCurr, baseAmt});
            while (!q.empty()) {
                auto [curr, amt] = q.front();
                q.pop();
                for (const auto& [nxt, r] : graph[curr]) {
                    double newAmt = amt * r;
                    if (newAmt > best[nxt] * 1.0000001) {
                        best[nxt] = newAmt;
                        q.push({nxt, newAmt});
                    }
                }
            }
            return best;
        };

        auto day1Holdings = getMaxHoldings(initialCurrency, 1.0, pairs1, rates1);
        double ans = 1.0;
        for (const auto& [curr, amt] : day1Holdings) {
            auto day2Holdings = getMaxHoldings(curr, amt, pairs2, rates2);
            if (day2Holdings.contains(initialCurrency)) {
                ans = max(ans, day2Holdings[initialCurrency]);
            }
        }
        return ans;
    }
};

class Solution {
    public double maxAmount(String initialCurrency, List<List<String>> pairs1, double[] rates1, List<List<String>> pairs2, double[] rates2) {
        Map<String, Double> day1Holdings = getMaxHoldings(initialCurrency, 1.0, pairs1, rates1);
        double ans = 1.0;
        for (Map.Entry<String, Double> entry : day1Holdings.entrySet()) {
            Map<String, Double> day2Holdings = getMaxHoldings(entry.getKey(), entry.getValue(), pairs2, rates2);
            if (day2Holdings.containsKey(initialCurrency)) {
                ans = Math.max(ans, day2Holdings.get(initialCurrency));
            }
        }
        return ans;
    }

    private Map<String, Double> getMaxHoldings(String startCurr, double baseAmt, List<List<String>> pairs, double[] rates) {
        Map<String, List<Pair>> graph = new HashMap<>();
        for (int i = 0; i < pairs.size(); ++i) {
            String u = pairs.get(i).get(0), v = pairs.get(i).get(1);
            double r = rates[i];
            graph.computeIfAbsent(u, k -> new ArrayList<>()).add(new Pair(v, r));
            graph.computeIfAbsent(v, k -> new ArrayList<>()).add(new Pair(u, 1.0 / r));
        }
        Map<String, Double> best = new HashMap<>();
        best.put(startCurr, baseAmt);
        Queue<Pair> q = new ArrayDeque<>();
        q.offer(new Pair(startCurr, baseAmt));
        while (!q.isEmpty()) {
            Pair top = q.poll();
            String curr = top.curr; double amt = top.rate;
            if (!graph.containsKey(curr)) continue;
            for (Pair edge : graph.get(curr)) {
                double newAmt = amt * edge.rate;
                if (newAmt > best.getOrDefault(edge.curr, 0.0) * 1.0000001) {
                    best.put(edge.curr, newAmt);
                    q.offer(new Pair(edge.curr, newAmt));
                }
            }
        }
        return best;
    }

    private static class Pair {
        String curr;
        double rate;
        Pair(String c, double r) { curr = c; rate = r; }
    }
}

var maxAmount = function(initialCurrency, pairs1, rates1, pairs2, rates2) {
    const getMaxHoldings = (startCurr, baseAmt, pairs, rates) => {
        const graph = new Map();
        for (let i = 0; i < pairs.length; i++) {
            const [u, v] = pairs[i];
            const r = rates[i];
            if (!graph.has(u)) graph.set(u, []);
            if (!graph.has(v)) graph.set(v, []);
            graph.get(u).push([v, r]);
            graph.get(v).push([u, 1.0 / r]);
        }
        const best = new Map([[startCurr, baseAmt]]);
        const q = [[startCurr, baseAmt]];
        while (q.length > 0) {
            const [curr, amt] = q.shift();
            for (const [nxt, r] of graph.get(curr) || []) {
                const newAmt = amt * r;
                if (newAmt > (best.get(nxt) || 0) * 1.0000001) {
                    best.set(nxt, newAmt);
                    q.push([nxt, newAmt]);
                }
            }
        }
        return best;
    };

    const day1Holdings = getMaxHoldings(initialCurrency, 1.0, pairs1, rates1);
    let ans = 1.0;
    for (const [curr, amt] of day1Holdings.entries()) {
        const day2Holdings = getMaxHoldings(curr, amt, pairs2, rates2);
        if (day2Holdings.has(initialCurrency)) {
            ans = Math.max(ans, day2Holdings.get(initialCurrency));
        }
    }
    return ans;
};
